for key,zh in revisions.items():
    r=records[key];s=r['source'];assert hashlib.sha256(s.encode()).hexdigest()==r['sha256']
    assert re.findall(r'<(?:/?[A-Za-z][^>]*|!--[\s\S]*?--)>',s)==re.findall(r'<(?:/?[A-Za-z][^>]*|!--[\s\S]*?--)>',zh),key
    before=full.get(s);full[s]=zh;report.append({'key':key,'sha256':r['sha256'],'changed':before!=zh,'method':'human-full-field','source':s,'zh':zh})
(BASE/'editorial-records.json').write_text(json.dumps(full,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(ROOT/'localization/annotations/editorial-review.json').write_text(json.dumps({'checkedAt':'2026-10-08','reviewedUniqueSources':len(report),'revisions':report},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(f'Human reviewed {len(report)} unique source fields; stored independently of game data.')
